/**
 * Read — and set — the length of the codes Supabase mails.
 *
 * The admin verification code is generated by Supabase Auth (GoTrue) and
 * rendered into `{{ .Token }}`. How many digits it has is the project's
 * `mailer_otp_length`, exposed in the dashboard as "Email OTP Length" under
 * Authentication → Providers → Email. GoTrue accepts 6 to 10 and validates
 * that range itself; projects created more recently default to 8.
 *
 * Nothing in FayTarra can change it, which is why this talks to Supabase's
 * Management API instead of to the app.
 *
 *   # what is it now?
 *   SUPABASE_ACCESS_TOKEN=sbp_... SUPABASE_PROJECT_REF=abcd... \
 *     node scripts/supabase-otp-length.mjs
 *
 *   # set it to six
 *   SUPABASE_ACCESS_TOKEN=sbp_... SUPABASE_PROJECT_REF=abcd... \
 *     node scripts/supabase-otp-length.mjs --set 6
 *
 * The access token is a Supabase personal access token, from
 * https://supabase.com/dashboard/account/tokens. It is read from the
 * environment, never written anywhere, and never printed — not even in the
 * error paths below.
 */

const TOKEN = process.env.SUPABASE_ACCESS_TOKEN;
const REF = process.env.SUPABASE_PROJECT_REF;
const API = 'https://api.supabase.com';

if (!TOKEN || !REF) {
  console.error(
    'Usage: SUPABASE_ACCESS_TOKEN=sbp_... SUPABASE_PROJECT_REF=<ref> ' +
      'node scripts/supabase-otp-length.mjs [--set 6]\n\n' +
      '  access token: https://supabase.com/dashboard/account/tokens\n' +
      '  project ref : the subdomain of your project URL, ' +
      'https://<ref>.supabase.co',
  );
  process.exit(2);
}

const wanted = process.argv.includes('--set')
  ? Number(process.argv[process.argv.indexOf('--set') + 1])
  : null;

if (wanted !== null && (!Number.isInteger(wanted) || wanted < 6 || wanted > 10)) {
  console.error(`--set takes a whole number from 6 to 10. GoTrue refuses anything else.`);
  process.exit(2);
}

const headers = { authorization: `Bearer ${TOKEN}`, 'content-type': 'application/json' };

async function call(method, body) {
  const response = await fetch(`${API}/v1/projects/${REF}/config/auth`, {
    method,
    headers,
    ...(body ? { body: JSON.stringify(body) } : {}),
  });
  if (!response.ok) {
    // Deliberately reports the STATUS, never the request — the Authorization
    // header must not end up in a terminal log or a screenshot.
    const detail = await response.text().catch(() => '');
    throw new Error(
      `${method} config/auth failed: ${response.status} ${response.statusText}` +
        (detail ? ` — ${detail.slice(0, 300)}` : ''),
    );
  }
  return response.json();
}

const describe = (config) => {
  const length = config.mailer_otp_length ?? '(unset — GoTrue default)';
  const seconds = config.mailer_otp_exp ?? '(unset)';
  console.log(`  mailer_otp_length  ${length}`);
  console.log(`  mailer_otp_exp     ${seconds} seconds`);
};

try {
  console.log(`\nProject ${REF} — current email OTP settings:`);
  const before = await call('GET');
  describe(before);

  if (wanted === null) {
    const length = Number(before.mailer_otp_length);
    console.log(
      length === 6
        ? '\n  ✓ Six digits, which is what FayTarra admin verification expects.'
        : `\n  ✗ FayTarra admin verification expects 6 digits, not ${length || 'this'}.` +
          `\n    Fix it with:  node scripts/supabase-otp-length.mjs --set 6`,
    );
    process.exit(length === 6 ? 0 : 1);
  }

  console.log(`\nSetting mailer_otp_length to ${wanted}…`);
  await call('PATCH', { mailer_otp_length: wanted });

  // Read it back rather than trusting the write. A PATCH that is accepted and
  // silently ignored looks exactly like one that worked.
  const after = await call('GET');
  console.log('\nNow:');
  describe(after);

  const ok = Number(after.mailer_otp_length) === wanted;
  console.log(
    ok
      ? `\n  ✓ Confirmed. The next code Supabase mails will have ${wanted} digits.`
      : `\n  ✗ The setting did not take — it still reads ${after.mailer_otp_length}.`,
  );
  process.exit(ok ? 0 : 1);
} catch (failure) {
  console.error(`\n${failure instanceof Error ? failure.message : failure}`);
  process.exit(1);
}
